class BizException extends Error {
  constructor(code, message){ super(message); this.code = code; this.biz = true; }
}

const handlers = [];
function ControllerAdvice(fn) { handlers.push(fn); }
function handle(err) {
  for (const h of handlers) {
    const r = h(err);
    if (r) return r;
  }
  return { code: 500, message: "系统错误", data: null };
}
ControllerAdvice(e => { if (e.biz) return { code: e.code, message: e.message, data: null }; });
ControllerAdvice(e => { if (e instanceof Error) return { code: 500, message: "系统繁忙", data: null }; });
function controller() {
  try {
    throw new BizException(1001, "用户不存在");
  } catch (e) {
    return handle(e);
  }
}
console.log(JSON.stringify(controller()));
